  auto cta_tiler = make_shape(Int<128>{}, Int<128>{}, Int<32>{});

  int row_start = blockIdx.x * 128;
  int col_start = blockIdx.y * 128;
  int col_end   = col_start + 127;

  auto cta_coord = make_coord((int)blockIdx.x, (int)blockIdx.y, _);
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1, _1, X>{}); // (128,128)
