  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step<X, _1, _1>{}); // (128,8,Ktiles)

  extern __shared__ unsigned char smem_raw[];
  T* smemA0 = reinterpret_cast<T*>(smem_raw);
  T* smemA1 = smemA0 + 128 * 33;
  T* smemB0 = smemA1 + 128 * 33;
  T* smemB1 = smemB0 + 128 * 33;
  Tensor sA0 = make_tensor(make_smem_ptr(smemA0), make_shape(Int<128>{}, Int<32>{}), make_stride(Int<33>{}, Int<1>{}));
  Tensor sA1 = make_tensor(make_smem_ptr(smemA1), make_shape(Int<128>{}, Int<32>{}), make_stride(Int<33>{}, Int<1>{}));
  Tensor sB0 = make_tensor(make_smem_ptr(smemB0), make_shape(Int<128>{}, Int<32>{}), make_stride(Int<33>{}, Int<1>{}));
  Tensor sB1 = make_tensor(make_smem_ptr(smemB1), make_shape(Int<128>{}, Int<32>{}), make_stride(Int<33>{}, Int<1>{}));
  auto tA = make_layout(make_shape(Int<16>{}, Int<16>{}), make_stride(Int<16>{}, Int<1>{}));
  auto tB = make_layout(make_shape(Int<16>{}, Int<16>{}));
  // Row-major thread layout so consecutive threads map to consecutive
  // columns of the output tile (C is row-major / column-contiguous),
  // yielding fully coalesced global memory writes to C.
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}), make_stride(Int<16>{}, Int<1>{}));
  Tensor tAgA = local_partition(gA, tA, threadIdx.x);
  Tensor tAsA0 = local_partition(sA0, tA, threadIdx.x);
  Tensor tAsA1 = local_partition(sA1, tA, threadIdx.x);
  Tensor tBgB = local_partition(gB, tB, threadIdx.x);
  Tensor tBsB0 = local_partition(sB0, tB, threadIdx.x);
  Tensor tBsB1 = local_partition(sB1, tB, threadIdx.x);
  Tensor tCsA0 = local_partition(sA0, tC, threadIdx.x, Step<_1, X>{});
  Tensor tCsA1 = local_partition(sA1, tC, threadIdx.x, Step<_1, X>{});
  Tensor tCsB0 = local_partition(sB0, tC, threadIdx.x, Step<X, _1>{});
  Tensor tCsB1 = local_partition(sB1, tC, threadIdx.x, Step<X, _1>{});
  Tensor tCgC = local_partition(gC, tC, threadIdx.x, Step<_1, _1>{});
  // Identity coordinate tensor partitioned the same way as gC, used for masking.
  Tensor cC   = make_identity_tensor(shape(gC));
  Tensor tCcC = local_partition(cC, tC, threadIdx.x, Step<_1, _1>{});
  Tensor tCrC = make_tensor_like(tCgC);
  clear(tCrC);
