  for (int i = 0; i < k_tile_count; ++i) {
    int cur = i & 1;
    if (i + 1 < k_tile_count) {
      int k_tile_next = k_tile_lo + i + 1;
      if (((i + 1) & 1) == 0) {
        copy(tAgA(_, _, k_tile_next), tAsA0);
        copy(tBgB(_, _, k_tile_next), tBsB0);
